using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController:Controller{
 readonly ApiClient api;public OrganiserController(ApiClient a)=>api=a;
 bool Guard()=>HttpContext.Session.GetString("Role")=="Organiser";
 public async Task<IActionResult> Index(){if(!Guard())return RedirectToAction("Login","Account");var es=await api.Get<List<RaceEventDto>>("api/events")??new();var counts=new Dictionary<int,int>();foreach(var e in es){var x=await api.Get<List<EnrolmentDto>>($"api/events/{e.EventId}/enrolments");counts[e.EventId]=x?.Count??0;}ViewBag.Counts=counts;return View(es);}
 public IActionResult Create(){if(!Guard())return RedirectToAction("Login","Account");return View(new EventVm());}
 [HttpPost, ValidateAntiForgeryToken]public async Task<IActionResult>Create(EventVm vm){if(!Guard())return Forbid();if(!ModelState.IsValid)return View(vm);var r=await api.Send("POST","api/events",new{name=vm.Name,description=vm.Description,eventDate=vm.EventDate,location=vm.Location,distanceKm=vm.DistanceKm,eventType=vm.EventType});if(!r.Ok){ModelState.AddModelError("",r.Error);return View(vm);}var list=await api.Get<List<RaceEventDto>>("api/events")??new();var created=list.OrderByDescending(x=>x.EventId).FirstOrDefault(x=>x.Name==vm.Name);if(created!=null&&vm.BannerImage!=null)await api.Upload($"api/events/{created.EventId}/banner",vm.BannerImage);TempData["Success"]="Event created.";return RedirectToAction("Index");}
 public async Task<IActionResult>Edit(int id){if(!Guard())return Forbid();var e=await api.Get<RaceEventDto>($"api/events/{id}");if(e==null)return NotFound();return View(new EventVm{EventId=id,Name=e.Name,Description=e.Description,EventDate=e.EventDate,Location=e.Location,DistanceKm=e.DistanceKm,EventType=e.EventType});}
 [HttpPost, ValidateAntiForgeryToken]public async Task<IActionResult>Edit(EventVm vm){if(!Guard())return Forbid();if(!ModelState.IsValid)return View(vm);var r=await api.Send("PUT",$"api/events/{vm.EventId}",new{name=vm.Name,description=vm.Description,eventDate=vm.EventDate,location=vm.Location,distanceKm=vm.DistanceKm,eventType=vm.EventType});if(!r.Ok){ModelState.AddModelError("",r.Error);return View(vm);}if(vm.BannerImage!=null)await api.Upload($"api/events/{vm.EventId}/banner",vm.BannerImage);TempData["Success"]="Event updated.";return RedirectToAction("Index");}
 [HttpPost, ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id){if(!Guard())return Forbid();var r=await api.Send("DELETE",$"api/events/{id}");TempData[r.Ok?"Success":"Error"]=r.Ok?"Event deleted.":r.Error;return RedirectToAction("Index");}
 public async Task<IActionResult>Categories(int id){if(!Guard())return Forbid();ViewBag.Event=await api.Get<RaceEventDto>($"api/events/{id}");ViewBag.Categories=await api.Get<List<CategoryDto>>($"api/events/{id}/categories")??new();return View(new CategoryVm{ });}
 [HttpPost, ValidateAntiForgeryToken]public async Task<IActionResult>AddCategory(int id,CategoryVm vm){if(!Guard())return Forbid();var r=await api.Send("POST",$"api/events/{id}/categories",new{name=vm.Name,categoryType=vm.CategoryType});TempData[r.Ok?"Success":"Error"]=r.Ok?"Category added.":r.Error;return RedirectToAction("Categories",new{id});}
 [HttpPost, ValidateAntiForgeryToken]public async Task<IActionResult>DeleteCategory(int id,int categoryId){if(!Guard())return Forbid();var r=await api.Send("DELETE",$"api/events/{id}/categories/{categoryId}");TempData[r.Ok?"Success":"Error"]=r.Ok?"Category removed.":r.Error;return RedirectToAction("Categories",new{id});}
 public async Task<IActionResult>Enrolments(int id){if(!Guard())return Forbid();ViewBag.Event=await api.Get<RaceEventDto>($"api/events/{id}");var rows=await api.Get<List<EnrolmentDto>>($"api/events/{id}/enrolments")??new();return View(rows);}
 [HttpPost, ValidateAntiForgeryToken]public async Task<IActionResult>CaptureResult(int id,ResultVm vm){if(!Guard())return Forbid();var r=await api.Send("POST",$"api/events/{id}/results",new{enrolmentId=vm.EnrolmentId,finishTime=vm.FinishTime,finishPosition=vm.FinishPosition});TempData[r.Ok?"Success":"Error"]=r.Ok?"Result recorded.":r.Error;return RedirectToAction("Enrolments",new{id});}
}
